import * as fs from 'fs';
import * as fsp from 'fs/promises';
import * as path from 'path';
import { PreviewOverrides } from './types';

/**
 * qnav-owned data directory. Everything generated by previewing or capturing
 * lives here — never inside the projects being previewed.
 */
export class DataStore {
  readonly root: string;
  private overridesPath: string;
  private overrides: Record<string, PreviewOverrides> = {};
  private writeChain: Promise<void> = Promise.resolve();

  constructor(root: string) {
    this.root = root;
    this.overridesPath = path.join(root, 'overrides.json');
  }

  async init(): Promise<void> {
    await fsp.mkdir(this.root, { recursive: true });
    await fsp.mkdir(path.join(this.root, 'captures'), { recursive: true });
    this.overrides = (await this.readJson(this.overridesPath)) || {};
  }

  getOverrides(projectId: string): PreviewOverrides | undefined {
    return this.overrides[projectId];
  }

  async setOverrides(projectId: string, patch: Partial<PreviewOverrides>): Promise<PreviewOverrides> {
    const prev = this.overrides[projectId] || { revision: 0 };
    const next: PreviewOverrides = { ...prev, ...patch, revision: (prev.revision || 0) + 1, updatedAt: new Date().toISOString() };
    // Drop empty strings so "clear" works.
    for (const key of Object.keys(next) as (keyof PreviewOverrides)[]) {
      if ((next as any)[key] === '' || (next as any)[key] === null) delete (next as any)[key];
    }
    this.overrides[projectId] = next;
    await this.writeJson(this.overridesPath, this.overrides);
    return next;
  }

  async clearOverrides(projectId: string): Promise<void> {
    delete this.overrides[projectId];
    await this.writeJson(this.overridesPath, this.overrides);
  }

  filePath(...segments: string[]): string {
    return path.join(this.root, ...segments);
  }

  async readJson<T = any>(file: string): Promise<T | null> {
    try {
      const raw = await fsp.readFile(file, 'utf-8');
      return JSON.parse(raw) as T;
    } catch {
      return null;
    }
  }

  /** Atomic, serialised JSON write (tmp file + rename). */
  writeJson(file: string, value: unknown): Promise<void> {
    this.writeChain = this.writeChain.then(async () => {
      await fsp.mkdir(path.dirname(file), { recursive: true });
      const tmp = `${file}.${process.pid}.tmp`;
      await fsp.writeFile(tmp, JSON.stringify(value, null, 2), 'utf-8');
      await fsp.rename(tmp, file);
    }).catch(err => {
      console.error('DataStore write failed:', err);
    });
    return this.writeChain;
  }

  existsSync(file: string): boolean {
    return fs.existsSync(file);
  }
}
